using NUnit.Framework;

[TestFixture]
public class AllLettersUniqueTests
{
    [TestCase("abc", true)]
    [TestCase("Hello", false)]
    public void Checks_Uniqueness(string word, bool expected)
    {
        Assert.That(AllLettersUnique(word), Is.EqualTo(expected));
    }

    private bool AllLettersUnique(string word)
    {
        var seen = new HashSet<char>();

        foreach (var ch in word.ToLowerInvariant())
        {
            if (!char.IsLetter(ch))
                continue;

            if (!seen.Add(ch))
                return false;
        }

        return true;
    }
}
